import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { ContactRecordPage } from '../../pages/ContactRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import { expectRecordTitle, recordIdFromView, showRelatedList, waitForSpinners } from '../../support/lightning.js';
import { soqlValue } from '../../support/api.js';

test.describe('SF-219 System Administrator can create and edit Contacts from Account (allow case)', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-012 System Administrator can create and edit Contacts from Account (allow case)',
    { tag: ['@functional', '@P0', '@SF-219', '@persona:system-admin', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P0',
        severity: 'critical',
        feature: 'Account',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-012',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const contactRecordPage = new ContactRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const viewed: Record<string, string> = {};
      await data.create('account-contact', ['Account', 'Contact']);
      await test.step("1. Navigate to the Account record 'Acme Test' and open the Contacts related list", async () => {
        // Expected (DECLARED_CONFIG; ObjectPermissions:Profile:System Administrator.Contact): Contacts related list displays a 'New' button
        await accountRecordPage.open(data.id('Account'));
        await expect(accountRecordPage.contactsNewButton).toBeVisible();
      });
      await test.step("2. Click 'New' on the Contacts related list, fill Last Name = 'AdminTest', Account Name = 'Acme Test' (pre-populated), and click Save", async () => {
        // Expected (DECLARED_CONFIG; ObjectPermissions:Profile:System Administrator.Contact): Contact record is created; the Contact detail page opens and shows Last Name 'AdminTest' and Account Name 'Acme Test'
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await newContactDialog.lastName.fill('AdminTest');
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        viewed['createdContact'] = await recordIdFromView(page, 'Contact');
        await data.adoptCreated('createdContact', 'Contact', viewed['createdContact']);
        await expectRecordTitle(page, 'AdminTest');
        await expect(contactRecordPage.accountNameField).toContainText(data.value('Account', 'Name'));
        await expect.poll(() => soqlValue(sf, 'Contact', viewed['createdContact'] ?? '', 'LastName')).toBe('AdminTest');
      });
      await test.step("3. On the created Contact record, click Edit, change Last Name to 'AdminTestEdited', and click Save", async () => {
        // Expected (DECLARED_CONFIG; ObjectPermissions:Profile:System Administrator.Contact): Contact record is updated; the Contact detail page shows Last Name 'AdminTestEdited'
        await data.update('Contact', { LastName: 'AdminTestEdited' });
        await expect.poll(() => soqlValue(sf, 'Contact', data.id('Contact'), 'LastName')).toBe('AdminTestEdited');
      });
    },
  );
});
